def main() -> None:
    print()
    print("=" * 76)
    print("PHILOTES BACKEND EMAIL DELIVERY V1.2")
    print("=" * 76)
    print()

    required_dirs = [
        BACKEND_ROOT, APP_ROOT, APP_ROOT / "api", APP_ROOT / "api" / "routes",
        APP_ROOT / "core", APP_ROOT / "models", APP_ROOT / "repositories",
        APP_ROOT / "schemas", APP_ROOT / "security", APP_ROOT / "services",
        APP_ROOT / "presentation",
        TEST_ROOT, ALEMBIC_ROOT, ALEMBIC_ROOT / "versions",
    ]
    for path in required_dirs:
        if not path.exists():
            print(f"FAIL: Required folder not found: {path}")
            raise SystemExit(1)
    if not ALEMBIC_INI.exists():
        print(f"FAIL: Alembic configuration not found: {ALEMBIC_INI}")
        raise SystemExit(1)

    titan_logo_source = (
        PROJECT_ROOT / "assets" / "branding" / "titan-logo.png"
    )
    if not titan_logo_source.exists():
        print(
            "FAIL: Approved Titan logo asset not found: "
            f"{titan_logo_source}"
        )
        raise SystemExit(1)

    titan_logo_target = (
        APP_ROOT / "static" / "branding" / "titan-logo.png"
    )

    originals = {path: path.read_text(encoding="utf-8") if path.exists() else None for path in FILES}
    original_titan_logo = (
        titan_logo_target.read_bytes()
        if titan_logo_target.exists()
        else None
    )
    try:
        for path, content in FILES.items():
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_text(content, encoding="utf-8")

        titan_logo_target.parent.mkdir(parents=True, exist_ok=True)
        titan_logo_target.write_bytes(titan_logo_source.read_bytes())
    except Exception as exc:
        for path, original in originals.items():
            if original is None:
                if path.exists(): path.unlink()
            else:
                path.write_text(original, encoding="utf-8")

        if original_titan_logo is None:
            if titan_logo_target.exists():
                titan_logo_target.unlink()
        else:
            titan_logo_target.parent.mkdir(parents=True, exist_ok=True)
            titan_logo_target.write_bytes(original_titan_logo)

        print(f"FAIL: {exc}")
        print("Existing backend files restored.")
        raise SystemExit(1)

    env_text = (ALEMBIC_ROOT / "env.py").read_text(encoding="utf-8")
